"""Build standalone CPU-only CAD tools; no dependencies or network requests."""
from pathlib import Path
import json

ROOT = Path(__file__).absolute().parent
BASE = 'https://chamanprakashkanth.github.io/Mechanical-Engineering-Market-Position-Dashboard/'
CSS = '''
:root{color-scheme:dark;--bg:#0b151c;--card:#142832;--line:#35515e;--ink:#f1f7f8;--muted:#bfd0da;--mint:#a8ecd2}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top right,#174a46,transparent 60%),var(--bg);color:var(--ink);font:17px/1.65 system-ui,sans-serif}header,main,footer{max-width:1140px;margin:auto;padding:24px}header{display:flex;flex-wrap:wrap;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line)}nav{display:flex;gap:20px;flex-wrap:wrap}a{color:var(--mint)}h1{font-size:clamp(34px,5vw,60px);line-height:1.1;letter-spacing:-.04em}h2{line-height:1.25}p,li{color:var(--muted)}.eyebrow{color:var(--mint);font-size:12px;letter-spacing:.15em;font-weight:bold}.layout{display:grid;grid-template-columns:1fr 1fr;gap:24px}.panel{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:24px;margin:20px 0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:block;font-size:14px}input,button{font:inherit;border-radius:9px;padding:11px;border:1px solid var(--line)}input{display:block;width:100%;background:#0b1b23;color:var(--ink);margin-top:6px}button{cursor:pointer;background:var(--mint);color:#0b2426;font-weight:bold}button:disabled{opacity:.45;cursor:not-allowed}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}.error{color:#ffb8a7}.stats{display:grid;grid-template-columns:1fr 1fr;gap:10px}.stat{background:#0b1b23;padding:12px;border-radius:10px}.stat strong{display:block;color:var(--mint);font-size:23px}svg{width:100%;height:240px;background:#0b1b23;border-radius:12px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--line)}code{color:var(--mint)}:focus-visible{outline:3px solid #fff;outline-offset:3px}@media(max-width:700px){.layout{grid-template-columns:1fr}header,main,footer{padding:18px}.fields{grid-template-columns:1fr}}@media print{header,button,footer{display:none}body,.panel{background:white;color:black}p,li,a{color:black}.layout{display:block}input{color:black;background:white}}
'''
JS = r'''
const $=id=>document.getElementById(id);
const mode=document.body.dataset.tool;
const fields=[...document.querySelectorAll('input')];
let model=null;
const n=id=>Number($(id).value);
const fmt=v=>Number(v.toFixed(5)).toString();
function save(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function dxfCircle(r){return `0\nCIRCLE\n8\n0\n10\n0\n20\n0\n30\n0\n40\n${fmt(r)}\n`;}
function dxf(m){return `0\nSECTION\n2\nHEADER\n9\n$ACADVER\n1\nAC1015\n9\n$INSUNITS\n70\n4\n0\nENDSEC\n0\nSECTION\n2\nENTITIES\n${dxfCircle(m.od/2)}${dxfCircle(m.bore/2)}0\nENDSEC\n0\nEOF\n`;}
function scad(m){return `// MechIntel original parametric ${mode}; dimensions in mm. CC0.\n// Nominal geometry only: verify material, tolerances and use before fabrication.\nouter_diameter = ${fmt(m.od)};\nbore_diameter = ${fmt(m.bore)};\nlength = ${fmt(m.length)};\n$fn = 128;\nassert(outer_diameter > bore_diameter && bore_diameter > 0 && length > 0);\ndifference() {\n  cylinder(d=outer_diameter, h=length);\n  translate([0,0,-0.1]) cylinder(d=bore_diameter,h=length+0.2);\n}\n`;}
function update(){
 model=null;
 let valid=fields.every(f=>f.value.trim()!=='' && Number.isFinite(Number(f.value)) && f.checkValidity());
 let err='Enter finite values within the displayed ranges.';
 if(valid && mode==='assembly' && (n('bearingTol')>=n('bearing') || n('spacerTol')>=n('spacer') || n('housingTol')>=n('housing'))){valid=false;err='Each tolerance must be smaller than its nominal dimension, so minimum dimensions remain positive.';}
 if(valid && mode==='assembly'){
  const b=n('bearing'),bt=n('bearingTol'),s=n('spacer'),st=n('spacerTol'),h=n('housing'),ht=n('housingTol');
  const stack=2*b+s,tol=2*bt+st,gap=h-stack,min=gap-ht-tol,max=gap+ht+tol;
  $('results').innerHTML=`<div class="stat">Nominal clearance<strong>${fmt(gap)} mm</strong></div><div class="stat">Worst-case clearance<strong>${fmt(min)} to ${fmt(max)} mm</strong></div>`;
  $('outcome').textContent=min>0?'Clearance throughout the entered limits.':max<0?'Interference throughout the entered limits.':'Limits include zero clearance or interference; review the assembly requirement.';
  $('equation').textContent=`${fmt(h)} − (2 × ${fmt(b)} + ${fmt(s)}) = ${fmt(gap)} mm; worst-case tolerance = ±${fmt(ht+tol)} mm.`;
  $('diagram').innerHTML='<rect x="15" y="45" width="330" height="90" fill="none" stroke="#a8ecd2"/><rect x="30" y="60" width="65" height="60" fill="#569baf"/><rect x="95" y="75" width="160" height="30" fill="#a8ecd2"/><rect x="255" y="60" width="65" height="60" fill="#569baf"/><text x="30" y="165" fill="#bfd0da">Bearing + spacer + bearing inside housing</text>';
 }else if(valid){
  const od=n('od'),shaft=n('shaft'),clearance=n('clearance'),length=n('length'),density=n('density'),bore=shaft+clearance;
  if(od<=bore){valid=false;err='Outside diameter must exceed the calculated bore diameter.';}
  else{model={od,bore,length,shaft,clearance,density};const volume=Math.PI/4*(od*od-bore*bore)*length;
   $('results').innerHTML=`<div class="stat">Bore diameter<strong>${fmt(bore)} mm</strong></div><div class="stat">Radial wall<strong>${fmt((od-bore)/2)} mm</strong></div><div class="stat">Material volume<strong>${fmt(volume/1000)} cm³</strong></div><div class="stat">Ideal solid mass<strong>${fmt(volume/1000*density)} g</strong></div>`;
   $('equation').textContent=`Bore = ${fmt(shaft)} + ${fmt(clearance)} = ${fmt(bore)} mm. Volume = π/4 × (${fmt(od)}² − ${fmt(bore)}²) × ${fmt(length)} mm³.`;
   const inner=90*bore/od;
   $('diagram').innerHTML=`<circle cx="125" cy="115" r="90" fill="#a8ecd2"/><circle cx="125" cy="115" r="${inner}" fill="#0b1b23"/><text x="230" y="90" fill="#bfd0da">OD ${fmt(od)} mm</text><text x="230" y="120" fill="#bfd0da">Bore ${fmt(bore)} mm</text><text x="230" y="150" fill="#bfd0da">Length ${fmt(length)} mm</text>`;
   $('outcome').textContent='Nominal geometry ready. Preview is a front section; DXF contains two concentric circles.';
  }
 }
 $('error').textContent=valid?'':err;
 document.querySelectorAll('[data-download]').forEach(b=>b.disabled=!valid);
 if(!valid){$('results').replaceChildren();$('equation').textContent='';$('diagram').replaceChildren();$('outcome').textContent='Correct the inputs to update the preview.';}
}
fields.forEach(f=>f.addEventListener('input',update));
document.querySelectorAll('[data-download]').forEach(b=>b.addEventListener('click',()=>{update();if(!model)return;const format=b.dataset.download;if(format==='scad')save(`mechintel-${mode}.scad`,scad(model),'text/plain');if(format==='dxf')save(`mechintel-${mode}-profile.dxf`,dxf(model),'application/dxf');if(format==='json')save(`mechintel-${mode}-dimensions.json`,JSON.stringify({units:'mm',tool:mode,...model},null,2),'application/json');}));
$('reset').addEventListener('click',()=>{fields.forEach(f=>f.value=f.defaultValue);update();});
$('print').addEventListener('click',()=>window.print());
update();
'''

def field(key,label,value,minimum,maximum,step='any'):
    return f'<label for="{key}">{label}<input id="{key}" type="number" value="{value}" min="{minimum}" max="{maximum}" step="{step}" required></label>'

PAGES = [
 ('shaft-spacer-generator','spacer','Custom Shaft Spacer CAD Generator','Enter a shaft diameter, diametral clearance, outside diameter and length to generate a tubular spacer. Download editable OpenSCAD and a 2D DXF profile.',
  field('od','Outside diameter (mm)',24,.001,10000)+field('shaft','Shaft diameter (mm)',12,.001,9999)+field('clearance','Diametral clearance (mm)',.2,0,1000)+field('length','Spacer length (mm)',20,.001,10000)+field('density','Material density (g/cm³)',7.85,.001,30),
  '<h2>How do I size a shaft spacer?</h2><p>Set the bore to the shaft diameter plus the intended diametral clearance. Set the outside diameter for your mating faces and choose the spacer length from the assembly dimension chain. This tool generates nominal geometry; it does not determine a permissible load or a manufacturing fit.</p><h3>Worked example: 12 mm shaft spacer</h3><p>A 12 mm shaft with 0.2 mm diametral clearance needs a 12.2 mm bore. With a 24 mm outside diameter and 20 mm length, the radial wall is 5.9 mm and the material volume is approximately 6.71 cm³. At 7.85 g/cm³ the ideal solid mass is approximately 52.67 g.</p>'),
 ('shim-washer-generator','shim','Custom Shim Washer CAD & DXF Generator','Create a flat annular shim washer from bore, outside diameter and thickness. Calculate volume and ideal mass, then download OpenSCAD and DXF.',
  field('od','Outside diameter (mm)',30,.001,10000)+field('shaft','Shaft / reference bore diameter (mm)',16,.001,9999)+field('clearance','Added diametral clearance (mm)',.2,0,1000)+field('length','Shim thickness (mm)',.5,.001,10000)+field('density','Material density (g/cm³)',7.85,.001,30),
  '<h2>How do I calculate shim washer dimensions?</h2><p>The inner diameter equals the reference shaft diameter plus the chosen diametral clearance. Thickness is the axial adjustment supplied by one shim. Use a measured assembly gap to select thickness; this tool does not measure the gap or recommend a fit.</p><h3>Worked example: 0.5 mm shim</h3><p>For OD 30 mm, reference diameter 16 mm, diametral clearance 0.2 mm and thickness 0.5 mm, the bore is 16.2 mm. Volume is approximately 0.2504 cm³ and ideal solid mass is approximately 1.965 g at 7.85 g/cm³.</p>'),
 ('bearing-spacer-clearance-calculator','assembly','Bearing Spacer Assembly Clearance Calculator','Calculate nominal and worst-case axial clearance for two bearings and a spacer inside a housing. Includes a dimension-chain diagram and worked example.',
  field('bearing','Each bearing width (mm)',10,.001,10000)+field('bearingTol','Each bearing tolerance (± mm)',.02,0,1000)+field('spacer','Spacer length (mm)',20,.001,10000)+field('spacerTol','Spacer tolerance (± mm)',.03,0,1000)+field('housing','Available housing length (mm)',40.2,.001,30000)+field('housingTol','Housing tolerance (± mm)',.04,0,1000),
  '<h2>How do I calculate bearing spacer axial clearance?</h2><p>For this simple one-dimensional chain, clearance equals the available housing length minus two bearing widths and the spacer length. Worst-case minimum clearance uses the smallest housing and largest components; maximum clearance uses the largest housing and smallest components.</p><h3>Worked example</h3><p>Two bearings of 10 ±0.02 mm and a 20 ±0.03 mm spacer occupy 40 ±0.07 mm. A housing of 40.2 ±0.04 mm gives nominal clearance 0.2 mm and worst-case clearance from 0.09 to 0.31 mm.</p><p>This model assumes both bearings have the same nominal width and tolerance. It adds their worst-case tolerances separately. It excludes shoulders, retaining rings, thermal expansion, elastic deformation, bearing internal clearance and preload. Add those requirements to your actual assembly review.</p>')]

for slug,mode,title,description,fields,content in PAGES:
    url=BASE+'engineering-careers/'+slug+'.html'
    schema={'@context':'https://schema.org','@type':'WebApplication','name':title,'url':url,'description':description,'applicationCategory':'DesignApplication','operatingSystem':'Any modern browser','isAccessibleForFree':True}
    downloads='' if mode=='assembly' else '<button data-download="scad">Download OpenSCAD</button><button data-download="dxf">Download DXF profile</button><button data-download="json">Save dimensions</button>'
    links=' · '.join(f'<a href="{p[0]}.html">{p[2]}</a>' for p in PAGES if p[0]!=slug)
    exportinfo='' if mode=='assembly' else '<h2>What do the downloads contain?</h2><p><strong>OpenSCAD:</strong> an editable solid ring with bore, outside diameter and length parameters in millimetres. Open the source in OpenSCAD and render/export STL locally if needed.</p><p><strong>DXF:</strong> two concentric circles forming the nominal front profile, with millimetre unit metadata. Thickness is not represented in this 2D file. Confirm import units in your CAD/CAM software. These downloads contain no threads, chamfers, tolerances or STEP geometry.</p><p>Clearance is diametral: radial gap equals half of it. Mass assumes homogeneous solid material and excludes printed infill or process compensation. Material density is your input.</p>'
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | MechIntel</title><meta name="description" content="{description}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/mechintel-social-cover.png"><meta name="twitter:card" content="summary_large_image"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; base-uri 'none'; form-action 'none'"><style>{CSS}</style><script type="application/ld+json">{json.dumps(schema)}</script></head><body data-tool="{mode}"><header><a href="../index.html">MechIntel / Engineering Tools</a><nav><a href="cad-library.html">CAD Library</a><a href="gate-mechanical-books.html">GATE Books</a></nav></header><main><p class="eyebrow">FREE · LOCAL PROCESSING · NO SIGNUP</p><h1>{title}</h1><p>{description}</p><p>All calculations and file generation run locally on your CPU. No API requests, AI inference, GPU, analytics or uploads.</p><noscript><p>Enable JavaScript to use the calculator. The formulas, worked example and instructions below remain readable.</p></noscript><div class="layout"><section class="panel"><h2>Set your dimensions</h2><div class="fields">{fields}</div><p id="error" class="error" role="alert"></p><div class="actions">{downloads}<button id="reset">Reset example</button><button id="print">Print report</button></div></section><section class="panel"><h2>Dimension preview</h2><svg id="diagram" viewBox="0 0 420 230" role="img" aria-label="Nominal dimension diagram"></svg><p id="outcome" role="status"></p><div id="results" class="stats" aria-live="polite"></div><p id="equation"></p></section></div><section class="panel">{content}{exportinfo}<h2>Formulas and assumptions</h2><p>Annular area = π(OD² − bore²)/4. Volume = area × length. Convert mm³ to cm³ by dividing by 1000. Mass in grams = volume in cm³ × density in g/cm³. For the axial assembly, C = H − 2B − S and worst-case tolerance = T_H + 2T_B + T_S.</p><p>These are nominal educational geometry and dimension-chain tools. They do not certify strength, sealing, bearing preload, material selection or manufacturing suitability.</p><h2>Can I use this offline?</h2><p>Yes. Save this complete HTML page and reopen it locally. Styles, calculations and downloads are embedded; no external libraries or network services are needed.</p><h2>Related tools</h2><p>{links}</p><p>Explore the <a href="cad-library.html">mechanical CAD library</a> and <a href="gate-mechanical-manufacturing-industrial-engineering.html#limits-fits">limits and fits revision chapter</a>.</p><h2>References</h2><p>Geometry derivation: subtract the inner circular area from the outer circular area and extrude by the axial length. <a href="https://openscad.org/documentation.html">OpenSCAD documentation</a> explains cylinder and difference operations. <a href="https://help.autodesk.com/view/OARX/2025/ENU/?guid=GUID-747865D5-51F0-45F2-BEFE-9572DBC5B151">Autodesk DXF reference</a> documents the exchange format. Downloads are original CC0 geometry; this tool does not reproduce standards tables.</p></section></main><footer>MechIntel · Original deterministic tools · Updated 16 October 2026</footer><script>{JS}</script></body></html>'''
    (ROOT/'engineering-careers'/f'{slug}.html').write_text(html,encoding='utf-8')
print('Generated three standalone CAD tools.')
